using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace PokeLab.Boot.Editor
{
    /// <summary>
    /// Builds the playable scene from the designed layout.
    ///
    /// The layout is data, not a scene, deliberately: it is generated by a seeded script and
    /// gets regenerated whenever the design changes, so hand-placing 4,682 objects once would
    /// throw that away. This reads the flattened form produced by
    /// <c>Tools/Level/emit_unity_layout.py</c> and rebuilds the whole thing in one pass.
    ///
    /// Ground and water arrive pre-triangulated from that script rather than being generated
    /// here. Their heights come from analytic fields the placement Y values were sampled
    /// against, and reimplementing those fields in C# would create a second source of truth
    /// for the one number every prop's footing depends on.
    /// </summary>
    public static class LevelLayoutBuilder
    {
        private const string LayoutPath = "Assets/Game/Data/Levels/slice_layout_unity.json";
        private const string RootName = "Level";

        [MenuItem("Tools/Poké Lab/Level/Build Slice Layout")]
        public static void Build()
        {
            if (!File.Exists(LayoutPath))
            {
                Debug.LogError($"[Level] {LayoutPath} not found. Run Tools/Level/emit_unity_layout.py first.");
                return;
            }

            var layout = JsonUtility.FromJson<Layout>(File.ReadAllText(LayoutPath));
            if (layout?.objects == null)
            {
                Debug.LogError("[Level] Layout parsed but contained no objects.");
                return;
            }

            var existing = GameObject.Find(RootName);
            if (existing != null) UnityEngine.Object.DestroyImmediate(existing);

            var root = new GameObject(RootName);
            var parents = new Dictionary<string, Transform>();
            var prefabCache = new Dictionary<string, GameObject>();
            var missing = new HashSet<string>();

            try
            {
                BuildSurfaces(layout, root.transform, parents);
                BuildObjects(layout, root.transform, parents, prefabCache, missing);
                BuildAnchors(layout, root.transform, parents);
                BuildSpawn(layout, root.transform);
            }
            finally
            {
                EditorUtility.ClearProgressBar();
            }

            if (missing.Count > 0)
            {
                Debug.LogWarning($"[Level] {missing.Count} prefab path(s) could not be loaded. " +
                                 "Those objects were skipped:\n  " + string.Join("\n  ", missing));
            }

            Debug.Log($"[Level] Built '{RootName}': {layout.decks?.Length ?? 0} decks/ramps, " +
                      $"{layout.ledges?.Length ?? 0} ledges, {layout.water?.Length ?? 0} water, " +
                      $"{layout.objects.Length} objects, {layout.ambientAnchors?.Length ?? 0} anchors.");
        }

        private static void BuildSurfaces(Layout layout, Transform root, Dictionary<string, Transform> parents)
        {
            var groundMat = AssetDatabase.LoadAssetAtPath<Material>(
                "Assets/Game/Shaders/Materials/M_Terrain_Default.mat");
            var waterMat = AssetDatabase.LoadAssetAtPath<Material>(
                "Assets/Game/Shaders/Materials/M_Water_Lake.mat");

            foreach (var deck in layout.decks ?? Array.Empty<Surface>())
                CreateSurface(deck, ResolveParent(root, parents, "Terrain/Ground"), groundMat, true);

            foreach (var body in layout.water ?? Array.Empty<Surface>())
                CreateSurface(body, ResolveParent(root, parents, "Terrain/Water"), waterMat, false);

            // Ledges are the vertical face of a one-way drop. Without them a level change is
            // an invisible cliff: the deck simply stops and whatever was placed on the join
            // hangs in the air.
            var rockMat = AssetDatabase.LoadAssetAtPath<Material>(
                "Assets/Game/Shaders/Materials/M_Prop_Default.mat") ?? groundMat;
            foreach (var ledge in layout.ledges ?? Array.Empty<Surface>())
                CreateSurface(ledge, ResolveParent(root, parents, "Terrain/Ledges"), rockMat, true);
        }

        private static void CreateSurface(Surface surface, Transform parent, Material material, bool collide)
        {
            if (surface.vertices == null || surface.vertices.Length < 9) return;

            var mesh = new Mesh { name = surface.name };
            // Ground meshes exceed 65k vertices comfortably at 1 m spacing across eight decks.
            mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;

            var count = surface.vertices.Length / 3;
            var verts = new Vector3[count];
            var uvs = new Vector2[count];
            for (var i = 0; i < count; i++)
            {
                var x = surface.vertices[i * 3];
                var y = surface.vertices[i * 3 + 1];
                var z = surface.vertices[i * 3 + 2];
                verts[i] = new Vector3(x, y, z);
                // World-space planar UVs at one tile per metre, so the terrain shader's
                // texel density matches the sprite pixel grid regardless of deck size.
                uvs[i] = new Vector2(x, z);
            }

            mesh.vertices = verts;
            mesh.uv = uvs;
            mesh.triangles = surface.triangles;
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            var go = new GameObject(surface.name);
            go.transform.SetParent(parent, false);
            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            var renderer = go.AddComponent<MeshRenderer>();
            if (material != null) renderer.sharedMaterial = material;

            if (collide) go.AddComponent<MeshCollider>().sharedMesh = mesh;

            go.isStatic = true;
            SetLayer(go, "Terrain");
        }

        private static void BuildObjects(Layout layout, Transform root,
            Dictionary<string, Transform> parents, Dictionary<string, GameObject> cache,
            HashSet<string> missing)
        {
            var total = layout.objects.Length;
            for (var i = 0; i < total; i++)
            {
                if ((i & 127) == 0 &&
                    EditorUtility.DisplayCancelableProgressBar(
                        "Building level", $"{i} / {total}", i / (float)total))
                {
                    Debug.LogWarning("[Level] Build cancelled; the scene is incomplete.");
                    return;
                }

                var entry = layout.objects[i];
                if (string.IsNullOrEmpty(entry.prefab)) continue;

                if (!cache.TryGetValue(entry.prefab, out var prefab))
                {
                    prefab = AssetDatabase.LoadAssetAtPath<GameObject>(entry.prefab);
                    cache[entry.prefab] = prefab;
                }

                if (prefab == null)
                {
                    missing.Add(entry.prefab);
                    continue;
                }

                var instance = (GameObject)PrefabUtility.InstantiatePrefab(
                    prefab, ResolveParent(root, parents, entry.parent));
                if (instance == null) continue;

                instance.name = entry.name;
                instance.transform.localPosition = ToVector(entry.position);
                instance.transform.localEulerAngles = ToVector(entry.rotation);
                instance.transform.localScale = ToVector(entry.scale, Vector3.one);
                instance.isStatic = entry.@static;
                if (!string.IsNullOrEmpty(entry.layer)) SetLayer(instance, entry.layer);
                if (!string.IsNullOrEmpty(entry.tag) && entry.tag != "Untagged") TrySetTag(instance, entry.tag);
            }
        }

        private static void BuildAnchors(Layout layout, Transform root, Dictionary<string, Transform> parents)
        {
            foreach (var anchor in layout.ambientAnchors ?? Array.Empty<Anchor>())
            {
                // Anchors are empties. The VFX and audio directors resolve them by name and
                // attach their own emitters, so placing a live effect here would double up.
                var go = new GameObject($"Anchor_{anchor.type}_{anchor.name}");
                go.transform.SetParent(ResolveParent(root, parents, "Ambient"), false);
                go.transform.localPosition = ToVector(anchor.position);
            }
        }

        private static void BuildSpawn(Layout layout, Transform root)
        {
            var spawn = new GameObject("PlayerSpawn");
            spawn.transform.SetParent(root, false);
            spawn.transform.localPosition = ToVector(layout.playerSpawn);
        }

        private static Transform ResolveParent(Transform root, Dictionary<string, Transform> parents, string path)
        {
            if (string.IsNullOrEmpty(path)) return root;
            if (parents.TryGetValue(path, out var found)) return found;

            var current = root;
            var accumulated = "";
            foreach (var part in path.Split('/'))
            {
                if (string.IsNullOrEmpty(part)) continue;
                accumulated = string.IsNullOrEmpty(accumulated) ? part : accumulated + "/" + part;
                if (!parents.TryGetValue(accumulated, out var next))
                {
                    next = new GameObject(part).transform;
                    next.SetParent(current, false);
                    parents[accumulated] = next;
                }
                current = next;
            }
            return current;
        }

        private static void SetLayer(GameObject go, string layerName)
        {
            var layer = LayerMask.NameToLayer(layerName);
            if (layer < 0) return;
            foreach (var t in go.GetComponentsInChildren<Transform>(true)) t.gameObject.layer = layer;
        }

        private static void TrySetTag(GameObject go, string tag)
        {
            try { go.tag = tag; }
            catch (UnityException) { /* Undeclared tags are not worth failing a build over. */ }
        }

        private static Vector3 ToVector(float[] v, Vector3 fallback = default) =>
            v != null && v.Length >= 3 ? new Vector3(v[0], v[1], v[2]) : fallback;

        // --- Serialized shapes, matching emit_unity_layout.py --------------------------

        [Serializable]
        private sealed class Layout
        {
            public Surface[] decks;
            public Surface[] ledges;
            public Surface[] water;
            public Placement[] objects;
            public Anchor[] ambientAnchors;
            public float[] playerSpawn;
            public float cameraPitch;
            public float cameraDistance;
            public float cameraFov;
        }

        [Serializable]
        private sealed class Surface
        {
            public string name;
            public string material;
            public float[] vertices;
            public int[] triangles;
        }

        [Serializable]
        private sealed class Placement
        {
            public string prefab;
            public string name;
            public string parent;
            public float[] position;
            public float[] rotation;
            public float[] scale;
            public string layer;
            public string tag;
            public bool @static;
        }

        [Serializable]
        private sealed class Anchor
        {
            public string name;
            public string type;
            public float[] position;
        }
    }
}
